describe('ToolRegistry ESM registration', () => {
  // @spec specs/hal-engine-tool-input-validation/spec.md#9
  it('registers a valid static schema through an ES module import', () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => JSON.stringify(input)
    );
    expect(registry.has('get_weather')).toBe(true);
